package org.openapitools.server.api.model

import org.openapitools.server.api.model.ChatCompletionMessageToolCall
import org.openapitools.server.api.model.ChatCompletionResponseMessageAudio
import org.openapitools.server.api.model.ChatCompletionResponseMessageFunctionCall
import com.squareup.moshi.JsonClass

@JsonClass(generateAdapter = true)
data class ChatCompletionResponseMessage(
    /** The contents of the message. */
    val content: kotlin.String,
    /** The refusal message generated by the model. */
    val refusal: kotlin.String,
    /** The role of the author of this message. */
    val role: kotlin.String,
    /** The tool calls generated by the model, such as function calls. */
    val toolCalls: kotlin.collections.List<ChatCompletionMessageToolCall>? = null,
    val functionCall: ChatCompletionResponseMessageFunctionCall? = null,
    val audio: ChatCompletionResponseMessageAudio? = null
)
